<script setup lang="ts">
import { ref, computed, watch, onBeforeUnmount } from 'vue';
import { parseColor, rgbToHsv, toHex, hsvToRgb, makeColor, formatColor, type HSVA, type ColorValue, type ColorFormat } from './internal/color';
import { useFloating, type PopupPlacement } from './internal/floating';
import './styles/theme.css'; import './styles/field.css'; import './styles/floating.css'; import './styles/color-picker.css';
const props = withDefaults(defineProps<{ modelValue?: string; defaultValue?: string; format?: ColorFormat; showAlpha?: boolean; showText?: boolean; presets?: { label: string; colors: string[] }[] | string[]; disabled?: boolean; allowClear?: boolean; size?: 'sm' | 'md' | 'lg'; label?: string; hint?: string; error?: string; placeholder?: string; open?: boolean; placement?: PopupPlacement }>(), { defaultValue: '#685cf6', format: 'hex', showText: true, size: 'md', placeholder: '选择颜色', placement: 'bottom-start' });
const emit = defineEmits<{ 'update:modelValue': [value: string]; change: [hex: string, color: ColorValue]; changeComplete: [hex: string, color: ColorValue]; 'update:open': [value: boolean] }>();
const inner = ref(props.defaultValue), innerOpen = ref(false); const current = computed(() => props.modelValue ?? inner.value); const opened = computed(() => (props.open ?? innerOpen.value) && !props.disabled); const hsv = ref(rgbToHsv(parseColor(current.value) ?? { r: 104, g: 92, b: 246, a: 1 })); const color = computed(() => makeColor(hsv.value)); const text = ref(formatColor(color.value.rgb, props.format)); const hue = computed(() => toHex(hsvToRgb({ h: hsv.value.h, s: 1, v: 1, a: 1 })));
watch([current, () => props.format], () => { const rgb = parseColor(current.value); if (rgb) { hsv.value = rgbToHsv(rgb); text.value = formatColor(rgb, props.format); } else text.value = ''; });
const groups = computed(() => !props.presets ? [] : typeof props.presets[0] === 'string' ? [{ label: '预设颜色', colors: props.presets as string[] }] : props.presets as { label: string; colors: string[] }[]);
let latest = current.value;
function complete() { emit('changeComplete', latest, color.value); }
function setOpen(value: boolean) { if (props.disabled) return; if (props.open === undefined) innerOpen.value = value; emit('update:open', value); if (!value) complete(); }
const { anchor, panel, position, resolvedPlacement } = useFloating(() => opened.value, () => props.placement, () => setOpen(false));
const clamp = (value: number) => Math.max(0, Math.min(1, value));
function apply(next: HSVA) { hsv.value = { ...next, a: props.showAlpha ? clamp(next.a) : 1, s: clamp(next.s), v: clamp(next.v) }; latest = toHex(hsvToRgb(hsv.value)); if (props.modelValue === undefined) inner.value = latest; text.value = formatColor(color.value.rgb, props.format); emit('update:modelValue', latest); emit('change', latest, color.value); }
let cleanup: (() => void) | undefined;
function drag(event: PointerEvent, kind: 'area' | 'hue' | 'alpha') { if (props.disabled) return; event.preventDefault(); cleanup?.(); const rect = (event.currentTarget as HTMLElement).getBoundingClientRect(); const move = (event: PointerEvent) => { const x = clamp((event.clientX - rect.left) / rect.width), y = clamp((event.clientY - rect.top) / rect.height); apply(kind === 'area' ? { ...hsv.value, s: x, v: 1 - y } : kind === 'hue' ? { ...hsv.value, h: x * 360 } : { ...hsv.value, a: x }); }; const up = () => { cleanup?.(); complete(); }; cleanup = () => { window.removeEventListener('pointermove', move); window.removeEventListener('pointerup', up); window.removeEventListener('pointercancel', up); }; move(event); window.addEventListener('pointermove', move); window.addEventListener('pointerup', up); window.addEventListener('pointercancel', up); }
onBeforeUnmount(() => cleanup?.());
function key(event: KeyboardEvent, kind: 'area' | 'hue' | 'alpha') { if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(event.key)) return; event.preventDefault(); const direction = ['ArrowLeft', 'ArrowDown'].includes(event.key) ? -1 : 1; const delta = event.shiftKey ? 0.1 : 0.01; if (kind === 'hue') apply({ ...hsv.value, h: (hsv.value.h + direction * delta * 100 + 360) % 360 }); else if (kind === 'alpha') apply({ ...hsv.value, a: hsv.value.a + direction * delta }); else if (['ArrowLeft', 'ArrowRight'].includes(event.key)) apply({ ...hsv.value, s: hsv.value.s + direction * delta }); else apply({ ...hsv.value, v: hsv.value.v + direction * delta }); complete(); }
function commit() { const rgb = parseColor(text.value); if (rgb) apply(rgbToHsv(rgb)); else text.value = formatColor(color.value.rgb, props.format); complete(); }
function preset(value: string) { const rgb = parseColor(value); if (rgb) { apply(rgbToHsv(rgb)); complete(); } }
function clear() { latest = ''; if (props.modelValue === undefined) inner.value = ''; emit('update:modelValue', ''); }
</script>
<template><div class="at-field"><label v-if="label" class="at-field__label">{{ label }}</label><div ref="anchor" :class="['at-selector', `at-selector--${size}`, 'at-color-picker', { 'at-color-picker--compact': !showText, 'at-selector--disabled': disabled, 'at-selector--error': error }]" role="combobox" :tabindex="disabled ? -1 : 0" aria-haspopup="dialog" :aria-expanded="opened" :aria-label="label ?? placeholder" @click="setOpen(!opened)" @keydown.enter.prevent="setOpen(!opened)" @keydown.space.prevent="setOpen(!opened)"><span :class="['at-color-picker__swatch', { 'at-color-picker__swatch--empty': !current }]" :style="{ '--at-swatch': current }" aria-hidden="true" /><span v-if="showText" class="at-selector__value at-color-picker__text">{{ current ? formatColor(parseColor(current) ?? color.rgb, format) : placeholder }}</span><button v-if="allowClear && current && !disabled" type="button" class="at-selector__clear" aria-label="清空颜色" @click.stop="clear">×</button></div><span v-if="error" class="at-field__error" role="alert">{{ error }}</span><span v-else-if="hint" class="at-field__hint">{{ hint }}</span><Teleport to="body"><div v-if="opened" ref="panel" class="at-popup at-color-picker__popup" :style="position" :data-placement="resolvedPlacement" role="dialog" :aria-label="label ?? placeholder"><div class="at-color-picker__area" :style="{ backgroundColor: hue }" @pointerdown="drag($event, 'area')"><span class="at-color-picker__area-handle" :style="{ left: `${hsv.s * 100}%`, top: `${(1 - hsv.v) * 100}%`, backgroundColor: toHex({ ...color.rgb, a: 1 }) }" role="slider" tabindex="0" aria-label="饱和度与明度" :aria-valuenow="Math.round(hsv.v * 100)" :aria-valuetext="`饱和度 ${Math.round(hsv.s * 100)}%，明度 ${Math.round(hsv.v * 100)}%`" @keydown="key($event, 'area')" /></div><div class="at-color-picker__sliders"><div class="at-color-picker__preview" :style="{ '--at-swatch': formatColor(color.rgb, 'rgb') }" aria-hidden="true" /><div class="at-color-picker__tracks"><div class="at-color-picker__hue" @pointerdown="drag($event, 'hue')"><span class="at-color-picker__slider-handle" :style="{ left: `${hsv.h / 360 * 100}%`, backgroundColor: hue }" role="slider" tabindex="0" aria-label="色相" :aria-valuemin="0" :aria-valuemax="360" :aria-valuenow="Math.round(hsv.h)" @keydown="key($event, 'hue')" /></div><div v-if="showAlpha" class="at-color-picker__alpha" :style="{ '--at-swatch': toHex({ ...color.rgb, a: 1 }) }" @pointerdown="drag($event, 'alpha')"><span class="at-color-picker__slider-handle" :style="{ left: `${hsv.a * 100}%`, backgroundColor: formatColor(color.rgb, 'rgb') }" role="slider" tabindex="0" aria-label="透明度" :aria-valuemin="0" :aria-valuemax="100" :aria-valuenow="Math.round(hsv.a * 100)" @keydown="key($event, 'alpha')" /></div></div></div><div class="at-color-picker__inputs"><span class="at-color-picker__format">{{ format.toUpperCase() }}</span><input v-model="text" class="at-color-picker__input" aria-label="颜色值" spellcheck="false" @blur="commit" @keydown.enter.prevent="commit"><span v-if="showAlpha" class="at-color-picker__alpha-text">{{ Math.round(hsv.a * 100) }}%</span></div><div v-for="group in groups" :key="group.label" class="at-color-picker__presets"><span class="at-popup__group">{{ group.label }}</span><div class="at-color-picker__preset-grid"><button v-for="value in group.colors" :key="value" type="button" class="at-color-picker__preset" :style="{ '--at-swatch': value }" :aria-label="value" :aria-pressed="value === current" @click="preset(value)" /></div></div></div></Teleport></div></template>
